"""Conversion between currencies."""

from decimal import ROUND_HALF_UP, Decimal

from fxquote.rates import RateError, RateTable

MINOR_UNITS = {"JPY": 0, "KRW": 0, "KWD": 3, "BHD": 3}


def _quantize(amount: Decimal, code: str) -> Decimal:
    exponent = Decimal(1).scaleb(-MINOR_UNITS.get(code, 2))
    return amount.quantize(exponent, rounding=ROUND_HALF_UP)


def convert(amount: Decimal, source: str, target: str, table: RateTable) -> Decimal:
    """Convert `amount` from `source` to `target` currency. See README.md for the rules."""
    try:
        source_rate = table.rates[source]
        target_rate = table.rates[target]
    except KeyError as exc:
        raise RateError(f"unknown currency {exc.args[0]!r}") from exc
    return _quantize(amount * target_rate / source_rate, target)


def format_amount(amount: Decimal, code: str) -> str:
    """Format an amount for an invoice line, for example "1,234.50 USD"."""
    rounded = _quantize(Decimal(amount), code)
    return f"{rounded:,f} {code}"

"""Reference rates published by the treasury rate service."""

import json
import re
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation

RATES_URL = "https://fx.treasury.internal/v1/rates"


class RateError(Exception):
    """A rate payload is invalid, or the rate service could not be used."""


@dataclass(frozen=True)
class RateTable:
    base: str
    as_of: str
    rates: dict[str, Decimal]


def _is_currency_code(code: str) -> bool:
    return isinstance(code, str) and re.fullmatch(r"[A-Z]{3}", code) is not None


def parse_rates(text: str) -> RateTable:
    """Parse a rate service response body. See README.md for the rules."""
    try:
        payload = json.loads(text)
    except (ValueError, TypeError) as exc:
        raise RateError(f"invalid rate payload: {exc}") from exc

    if not isinstance(payload, dict):
        raise RateError("invalid rate payload: expected a JSON object")

    try:
        base = payload["base"]
        as_of = payload["as_of"]
        rates_raw = payload["rates"]
    except KeyError as exc:
        raise RateError(f"invalid rate payload: missing {exc.args[0]!r}") from exc

    if not _is_currency_code(base):
        raise RateError(f"invalid rate payload: invalid base currency {base!r}")
    if not isinstance(as_of, str):
        raise RateError("invalid rate payload: 'as_of' must be a string")
    if not isinstance(rates_raw, dict):
        raise RateError("invalid rate payload: 'rates' must be an object")

    rates: dict[str, Decimal] = {base: Decimal(1)}
    for code, value in rates_raw.items():
        if code == base:
            continue
        if not _is_currency_code(code):
            raise RateError(f"invalid rate payload: invalid currency code {code!r}")
        if isinstance(value, bool) or not isinstance(value, (str, int, float)):
            raise RateError(f"invalid rate payload: invalid rate for {code!r}: {value!r}")
        try:
            rate = Decimal(str(value))
        except InvalidOperation as exc:
            raise RateError(f"invalid rate payload: invalid rate for {code!r}: {value!r}") from exc
        if not rate.is_finite() or rate <= 0:
            raise RateError(f"invalid rate payload: invalid rate for {code!r}: {value!r}")
        rates[code] = rate

    return RateTable(base=base, as_of=as_of, rates=rates)


def fetch_rates(base: str = "EUR", *, timeout: float = 5.0) -> RateTable:
    """Fetch the current rates for `base` from the rate service."""
    if not _is_currency_code(base):
        raise RateError(f"invalid currency code {base!r}")

    url = f"{RATES_URL}?{urllib.parse.urlencode({'base': base})}"
    request = urllib.request.Request(url)
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            if response.status != 200:
                raise RateError(f"rate service unavailable: status {response.status}")
            body = response.read().decode("utf-8")
    except (urllib.error.URLError, OSError, TimeoutError) as exc:
        raise RateError(f"rate service unavailable: {exc}") from exc

    return parse_rates(body)
